using System;
using System.Collections.Generic;
using System.Linq;
using UnityEngine;

/// <summary>
/// Sheet-music images for the songs in the <see cref="SongDatabase"/>, generated by Tools ▸ Songs ▸ Generate Sheet Music
/// (MusicXML → Verovio → PNG). Per song, in Assets/Resources/Sheets/&lt;songId&gt;/:
///   page-01.png, page-02.png, …   A4 pages, black notation on white (pixel size in SheetLayout.pages)
///   layout.json                     every bar's rectangle and every note's notehead rectangle on those pages, in pixels
///                                   (origin top-left), with the song's bar / beat / MIDI / hand — for highlighting.
///
///   var sheet = SheetLibrary.Get("fur_elise");
///   Texture2D page = sheet.pages[0];
///   foreach (var r in sheet.layout.BarRects(3)) ...         // where bar 3 is
///   foreach (var n in sheet.layout.NotesAt(3, 1f)) ...      // noteheads at bar 3, beat 1
/// </summary>
public static class SheetLibrary
{
    public const string ResourcesFolder = "Sheets";
    static readonly Dictionary<string, SheetMusic> s_cache = new Dictionary<string, SheetMusic>();

    /// <summary>Pages + layout for a song, or null if no sheet music was generated for it.</summary>
    public static SheetMusic Get(string songId)
    {
        if (string.IsNullOrEmpty(songId)) return null;
        if (s_cache.TryGetValue(songId, out var cached) && cached != null) return cached;

        var json = Resources.Load<TextAsset>($"{ResourcesFolder}/{songId}/layout")
                   ?? Resources.Load<TextAsset>($"{ResourcesFolder}/Local/{songId}/layout");
        if (json == null) { Debug.LogWarning($"[SheetLibrary] No sheet music for \"{songId}\". Run Tools ▸ Songs ▸ Generate Sheet Music."); return null; }
        var layout = JsonUtility.FromJson<SheetLayout>(json.text);
        string folder = layout.local ? $"{ResourcesFolder}/Local/{songId}" : $"{ResourcesFolder}/{songId}";
        var pages = layout.pages.Select(p => Resources.Load<Texture2D>($"{folder}/{System.IO.Path.GetFileNameWithoutExtension(p.file)}")).ToArray();
        var sheet = new SheetMusic { songId = songId, layout = layout, pages = pages };
        s_cache[songId] = sheet;
        return sheet;
    }

    public static void ClearCache() => s_cache.Clear();
}

public class SheetMusic
{
    public string songId;
    public SheetLayout layout;
    public Texture2D[] pages;   // index 0 = page 1
}

[Serializable]
public class SheetLayout
{
    public string songId;
    public bool local;               // lives under Sheets/Local/ (gitignored)
    public int barCount;             // SongData.BarCount
    public bool hasPickup;           // bar 1 has a pickup (drawn as its own short measure before bar 1)
    public List<SheetPage> pages = new List<SheetPage>();
    public List<SheetBar> bars = new List<SheetBar>();
    public List<SheetNote> notes = new List<SheetNote>();

    /// <summary>Rectangles of a bar (bar 1 can have two: the pickup and the first full bar).</summary>
    public IEnumerable<SheetBar> BarRects(int bar) => bars.Where(b => b.bar == bar);

    /// <summary>Noteheads that start at this bar + beat (all pieces of tied notes are separate entries; tied = false is the struck one).</summary>
    public IEnumerable<SheetNote> NotesAt(int bar, float beat) => notes.Where(n => n.bar == bar && Mathf.Abs(n.beat - beat) < 0.001f && !n.tied);

    /// <summary>Noteheads of one database note (index into SongDatabase.Get(songId).notes), including tied continuations.</summary>
    public IEnumerable<SheetNote> NotesOf(int noteIndex) => notes.Where(n => n.noteIndex == noteIndex);
}

[Serializable]
public class SheetPage
{
    public int index;                // 1-based
    public string file;              // page-01.png
    public int width, height;        // pixels
}

[Serializable]
public class SheetBar
{
    public int bar;                  // song bar number (1-based, as in SongData)
    public bool pickup;              // the pickup measure before bar 1
    public int page;                 // 1-based
    public float x, y, w, h;         // pixels, origin top-left
}

[Serializable]
public class SheetNote
{
    public int noteIndex;            // index into SongData.notes of the song
    public int bar;
    public float beat;
    public int midi;
    public string hand;              // "R" / "L"
    public bool tied;                // a tied continuation (not struck again)
    public int page;
    public float x, y, w, h;         // notehead rectangle, pixels, origin top-left
}
